#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Build a fully offline, zero-dependency HTML guide from reviewed JSON."""
import json
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parent

def build():
    data=json.loads((ROOT/'data/guide.json').read_text(encoding='utf-8'))
    styles=(ROOT/'assets/app.css').read_text(encoding='utf-8')
    js=(ROOT/'assets/app.js').read_text(encoding='utf-8')
    calcjs=(ROOT/'assets/calc.js').read_text(encoding='utf-8')
    serialized=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    resources='\n'.join(f'<div class="resource"><a target="_blank" rel="noopener noreferrer" href="{escape(s["url"],quote=True)}">{escape(s["title"])} ↗</a><div>{escape(s["org"])} · 核验 {escape(s["reviewed_at"])}</div></div>' for s in data['sources'])
    page=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="失业怎么办？被裁员后怎么办？按失业前、7天、3个月、6个月、1年拆解补偿、失业金、社保、医保、公积金、求职和现金流。免费离线开源指南，作者 AI 酋长 Andy。"><link rel="canonical" href="https://aipmandy.github.io/how-to-survive-unemployment/"><meta property="og:type" content="website"><meta property="og:url" content="https://aipmandy.github.io/how-to-survive-unemployment/"><meta property="og:title" content="失业怎么办？被裁员后怎么办？免费开源失业自救手册 · AI 酋长 Andy"><meta property="og:description" content="失业怎么办？被裁员后怎么办？按失业前、7天、3个月、6个月、1年拆解补偿、失业金、社保、医保、公积金、求职和现金流。免费离线开源指南，作者 AI 酋长 Andy。"><meta property="og:image" content="https://aipmandy.github.io/how-to-survive-unemployment/assets/social-preview.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="https://aipmandy.github.io/how-to-survive-unemployment/assets/social-preview.png"><script type="application/ld+json">{{"@context":"https://schema.org","@graph":[{{"@type":"Person","@id":"https://github.com/AIPMAndy#person","name":"AI 酋长 Andy","alternateName":["Andy Liu","AIPMAndy","AI Chief Andy","AI酋长Andy"],"url":"https://metaver.vip/","sameAs":["https://x.com/AIPMAndy","https://github.com/AIPMAndy","https://metaver.vip/","https://t.me/AIPMAndy"],"jobTitle":"连续创业者（AI + 产品方法论），前腾讯/百度 AI 产品专家，大模型独角兽前 VP","description":"AI 酋长 Andy（Andy Liu，GitHub/X @AIPMAndy）：前腾讯/百度 AI 产品专家，大模型独角兽前 VP，现专注 AI + 产品方法论创业。"}},{{"@type":"WebSite","@id":"https://aipmandy.github.io/how-to-survive-unemployment/#website","url":"https://aipmandy.github.io/how-to-survive-unemployment/","name":"失业了咋办？Andy 给你保姆级攻略","description":"失业怎么办？被裁员后怎么办？按失业前、7天、3个月、6个月、1年拆解补偿、失业金、社保、医保、公积金、求职和现金流。免费离线开源指南，作者 AI 酋长 Andy。","inLanguage":"zh-CN","author":{{"@id":"https://github.com/AIPMAndy#person"}},"publisher":{{"@id":"https://github.com/AIPMAndy#person"}}}}]}}</script><meta name="theme-color" content="#f6f7f8"><title>{escape(data['title'])}｜失业怎么办、被裁员后怎么办 · 开源版</title><style>{styles}</style></head><body><a class="skip" href="#main">跳到正文</a><header class="topbar"><div class="wrap"><a class="brand" href="#top">失业了咋办 <span aria-hidden="true">↗</span></a><nav class="toplinks" aria-label="主要导航"><a href="#actions">行动清单</a><a href="#tools">免费工具</a><a href="#sources">政策来源</a><button id="theme" class="quiet" type="button">深色模式</button></nav></div></header><main id="main"><div class="wrap"><section id="top" class="hero"><div><span class="eyebrow">OPEN SOURCE · 2026</span><h1>失业了咋办？<br><em>Andy 给你<br>保姆级攻略。</em></h1><p class="lede">失业前、前7天、3个月、6个月、1年。把该拿的钱拿清楚，先把医保和现金流稳住，再决定找工作还是做自己的生意。</p><div class="hero-actions"><a class="primary" href="#actions">开始自救清单 →</a><a class="secondary" href="#tools">计算还能撑几个月</a></div></div><aside class="hero-side" aria-label="项目核心"><div class="eyebrow">一份真正能用的指南</div><div class="big">35<span style="font-size:26px">项</span></div><div class="mini">可执行的失业应对任务</div><ul><li>先谈补偿，别急着签字</li><li>看懂北京、上海失业金</li><li>医保 / 社保 / 公积金接续</li><li>低成本求职与创业验证</li></ul></aside></section><div class="notice" role="note"><strong>政策注意：</strong>本项目更新日期 {escape(data['reviewed_at'])}。政策可能变化，且条件因人而异。法律、医保、税务和保险事项，请以当地官方最新答复为准。计算器仅用于预算，不存储或上传你的财务信息。</div><div class="kpis"><span><strong>5</strong>个时间阶段</span><span><strong>{len(data['tasks'])}</strong>项行动任务</span><span><strong>{len(data['sources'])}</strong>条官方来源</span><span><strong>0</strong>账号 / 安装 / 后端</span></div><section class="workspace" id="actions" aria-label="任务清单"><aside class="sidebar"><h2>按时间阶段浏览</h2><div class="stage-list" id="stage-list"></div><div class="sidefooter">勾选进度只保存在当前浏览器。清除浏览器存储后会重置。<p><button id="reset" class="quiet" type="button">清空本地进度</button></p></div></aside><div><section class="panel"><h2>现在先做哪件事？</h2><p class="sub">搜你的问题，或选一个时间阶段和地区。每张卡片都能展开具体步骤。</p><div class="toolbar"><input id="search" type="search" placeholder="搜索：N+1、医保、失业金、简历……" aria-label="搜索行动任务"><select id="city" aria-label="选择城市"><option value="all">全国 + 北京 + 上海</option><option value="beijing">全国 + 北京</option><option value="shanghai">全国 + 上海</option></select></div><div id="progress-track" role="progressbar" aria-label="已完成任务进度"><div id="progress-fill"></div></div><div class="progress-label"><span>已完成 <b id="done-count">0</b>/<span id="total-count">{len(data['tasks'])}</span> 项</span><span id="progress-pct">0%</span></div></section><div class="stagehead"><div><h2 id="stage-heading">全部行动清单</h2><p id="stage-intro">按时间阶段查看任务。</p></div><span id="shown-count" class="sub"></span></div><div id="tasks" class="tasks" aria-live="polite"></div></div></section><section class="tools" id="tools"><article class="panel tool"><h2>💰 家庭现金流计算器</h2><p class="sub">按最坏情况，手头的钱还够多久？输入金额单位为人民币元。</p><div class="form-grid"><label>可动用现金<input id="cash" type="number" inputmode="decimal" min="0" value="80000"></label><label>额外近期到期债务（未计入月支出）<input id="due" type="number" inputmode="decimal" min="0" value="10000"></label><label>每月必要支出<input id="expense" type="number" inputmode="decimal" min="0" value="10000"></label><label>每月确定收入<input id="income" type="number" inputmode="decimal" min="0" value="0"></label></div><div class="result">静态现金安全期<br><b id="runway">—</b></div><p id="calc-detail" class="note"></p><p class="note">谨慎：此处债务必须是【尚未计入每月支出】的额外到期款，否则会重复扣款。重大决策请优先填写13周现金流表；还应考虑突发医疗费、收入波动与投资流动性。</p></article><article class="panel tool"><h2>🗣️ HR 谈判话术</h2><p class="sub">收到解除通知时先确认事实，避免在压力下匆忙签字。</p><div id="hr-script" class="template">你好，我已收到公司关于岗位调整的沟通。请先明确此次解除是公司单方解除，还是希望与我协商解除；如属单方解除，请说明法律依据。也请将补偿计算方式、未结工资及奖金、离职证明、社保缴纳截止月份和支付日期整理成书面方案。我核对后再回复，谢谢。</div><div class="hero-actions"><button id="copy-script" class="secondary" type="button">复制话术</button><button id="download" class="primary" type="button">下载我的任务清单 ↓</button></div><p class="note">此话术不构成个案法律意见。遇到较大补偿争议，请咨询法律专业人士。</p></article></section></div><section id="sources" class="links"><h2>政策原文，不靠传言</h2><p class="sub">优先列官方文件。金额、资格和程序按个人实际情况重新核验。欢迎通过 GitHub Issue 提交城市政策更新。</p><div class="links-grid" style="margin-top:20px">{resources}</div></section></main><footer class="footer"><div class="wrap"><span>由 AI酋长 Andy 发起 · 开源免费 · 内容 CC BY 4.0 / 代码 MIT</span><span>愿你的王国自由且富足 · 更新于 {escape(data['reviewed_at'])}</span></div></footer><div id="toast" role="status" hidden></div><script id="guide-data" type="application/json">{serialized}</script><script>{calcjs}</script><script>{js}</script></body></html>'''

    # User decision routing. The application never sends answers outside the browser.
    triage_html = """<section class="decision panel" id="triage"><span class="eyebrow">STEP 0 · 3分钟判断</span><h2>别从头看到尾。先确认你现在处于哪一步。</h2><p class="sub">按真实情况选择，下面只给办理顺序，不会自动判断你具有法定资格。答案不会上传。</p><div class="form-grid"><label>目前状态<select id="status-select"><option value="negotiating">收到离职通知 / 还在协商</option><option value="unemployed">已经离职 / 暂时没工作</option><option value="longtime">失业3个月以上</option></select></label><label>需要办理的城市<select id="region-select"><option value="beijing">北京</option><option value="shanghai">上海</option><option value="else" selected>其他地区 / 尚不确定</option></select></label><label>离职事实<select id="leaving-select"><option value="unsure">原因尚不明确 / 存在争议</option><option value="employer">公司提出解除 / 裁员</option><option value="self">自己提出辞职</option></select></label><label>医保待遇<select id="coverage-select"><option value="unknown">不清楚</option><option value="active">查询显示正常</option><option value="gap">查询显示中断</option></select></label></div><div id="route-result" class="route-result" aria-live="polite"></div><p class="note">如果没有劳动合同、跨省参保、马上退休或已有失业保险领取记录，优先向经办机构核实个案，不要照搬计算结果。</p></section>"""
    assert '<section class="workspace"' in page
    page = page.replace('<section class="workspace"', triage_html + '<section class="workspace"', 1)
    weekly_html = """<article class="panel tool" id="weekly-planner"><h2>🧾 13周现金流自动计算</h2><p class="sub">直接填本周实际确定会到账的钱，以及到期要付的钱。周末余额自动计算，帮你找到第一周资金缺口。数据不上传。</p><label style="display:block;max-width:240px">第1周期初可动用现金（元）<input id="weekly-start" type="number" min="0" value="80000" inputmode="decimal"></label><details><summary class="secondary">展开填写13周账单</summary><div class="table-scroll"><table class="week-table"><thead><tr><th>周</th><th>确定流入</th><th>生活/住房</th><th>到期债务</th><th>其他必要</th><th>周末余额</th></tr></thead><tbody id="weekly-rows"></tbody></table></div></details><div class="result">第1个可能出现资金缺口的周<br><b id="first-negative">—</b></div><p id="weekly-detail" class="note"></p><button id="weekly-export" class="secondary" type="button">导出我填的13周CSV ↓</button><p class="note">**防重复计数：**如果房贷已填在“生活/住房”，不要又把同一期房贷填到“到期债务”。申请中但尚未核定的失业金、未到账补偿和口头订单，基础情景先填0。</p></article>"""
    extra_tools = """<article class="panel tool" id="labor-tool"><h2>🧮 N / 2N 补偿金额试算</h2><p class="sub">只用于核对算术。必须先判断是否依法属于经济补偿、代通知金或违法解除赔偿的情形。</p><div class="form-grid"><label>已工作完整年数<input id="work-years" type="number" min="0" max="80" step="1" value="3"></label><label>超出整年的月数<input id="work-months" type="number" min="0" max="11" step="1" value="8"></label><label>解除前12个月平均工资（元）<input id="avg-wage" type="number" min="0" value="15000"></label><label>上个月工资（仅提示不同口径）<input id="last-wage" type="number" min="0" value="15000"></label></div><div class="result">按工龄估算 N<br><b id="n-result">—</b></div><p id="labor-note" class="note"></p><p class="note">**特别注意：**没有处理高工资封顶、工龄争议、医疗期、合同类别等例外。2N仅在符合法定违法解除赔偿情形时可能适用；不自动把N+1或2N作为应赔金额。</p><p class="note"><a href="playbooks/01-labor-exit.html">完整法律情形及补偿表 →</a></p></article><article class="panel tool"><h2>📅 13周真实现金流表</h2><p class="sub">静态月度计算可能漏掉集中还款。按到账周和到期周逐笔填表，不能把同一笔房贷/债务重复扣除。</p><p><a class="secondary" href="templates/13-week-cashflow.csv" download>下载13周空白CSV ↓</a></p><p class="note"><a href="playbooks/03-cashflow-rescue.html">填写方法、风险预警、保守/基准情景</a></p></article>"""
    marker='</section></div><section id="sources"'
    assert marker in page
    page=page.replace(marker,weekly_html+extra_tools+'</section></div><section id="sources"',1)
    page=page.replace('35<span style="font-size:26px">项</span>', f'{len(data["tasks"])}<span style="font-size:26px">项</span>')
    page=page.replace('35项', f'{len(data["tasks"])}项')
    page=page.replace('>35<',f'>{len(data["tasks"])}<')
    # Optional author services sit beside the practical resources, without interrupting reading.
    consultation_html = """<aside class="consultation panel" id="consultation" aria-labelledby="consultation-title"><div><p class="consultation-label">作者咨询服务 · 按需了解</p><h2 id="consultation-title">想找个人一起梳理下一步？</h2><p>求职方向、简历与面试、职业转型，或 AI 应用与个人副业，都可以找这份手册的作者 AI酋长 Andy 聊聊。</p><p class="consultation-note">手册持续免费开放。咨询按需选择，服务范围与费用先沟通确认。</p></div><div class="consultation-contact"><p>微信 <strong id="wechat-id">AIPMAndy</strong></p><div class="consultation-actions"><button id="copy-wechat" class="secondary" type="button">复制微信号</button><a href="https://metaver.vip/" target="_blank" rel="noopener noreferrer">先了解 Andy ↗</a></div><p class="consultation-note">添加时备注「求职咨询」或你想聊的问题，简单说说目前的情况。</p></div></aside>"""
    tools_marker = '<section class="tools" id="tools">'
    assert tools_marker in page
    page = page.replace(tools_marker, consultation_html + tools_marker, 1)
    nav_marker = '<a href="#sources">政策来源</a>'
    assert nav_marker in page
    page = page.replace(nav_marker, nav_marker + '<a href="https://metaver.vip/" target="_blank" rel="noopener noreferrer">Andy 官网 ↗</a>', 1)
    footer_marker = '由 AI酋长 Andy 发起 · 开源免费 · 内容 CC BY 4.0 / 代码 MIT'
    page = page.replace(footer_marker, footer_marker + ' · <a href="https://metaver.vip/" target="_blank" rel="noopener noreferrer">作者官网</a> · 微信 AIPMAndy', 1)
    # FIELD NOTES V2 structure: visual storytelling only, all core JS hooks stay intact.
    page=page.replace('</div><aside class="hero-side"', "<div class=\"hero-proof\" aria-label=\"项目特点\"><span>免费开源</span><span>无需登录</span><span>进度保存在本机</span></div>" + '</div><aside class="hero-side"',1)
    page=page.replace('<footer class="footer"><div class="wrap">', '<footer class="footer">' + "<div class=\"footer-feature\"><span class=\"footer-index\">FIELD NOTES / OPEN-SOURCE SURVIVAL GUIDE</span><h2>人生不会因为一次失业，<br>就此定稿。</h2><nav aria-label=\"页脚快捷入口\"><a href=\"#actions\">行动清单 ↗</a><a href=\"#tools\">实用计算器 ↗</a><a href=\"guides/00-start-here.html\">阅读指南 ↗</a><a href=\"https://github.com/AIPMAndy/how-to-survive-unemployment\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub 开源 ↗</a></nav></div>" + '<div class="wrap">',1)
    page=page.replace('<meta name="theme-color" content="#f6f7f8">', '<meta name="theme-color" content="#f8f7f2">',1)
    (ROOT/'index.html').write_text(page,encoding='utf-8')
    from render_pages import write_all
    reader_count=write_all()
    print(f'Built {reader_count} offline readers')
    print(f'Built index.html: {len(data["tasks"])} tasks, {len(data["sources"])} official sources, {len(page):,} characters')
if __name__=='__main__':build()
